def summ(lid):
    r=res[lid]
    parts=[]
    for c in r.get("candidates",[]):
        parts.append(f"{c['invoice']}({c['payee']},{c['relation']},sim{c['payee_similarity']},diff{c['difference']})")
    print(lid,"amt",r.get("line_amount"),"|"," ; ".join(parts) if parts else "NO CANDIDATES")

for lid,_,_ in lines:
    summ(lid)

