async def decide(lid):
    kind = plan[lid][0]
    if kind=="esc":
        r = await escalate({"line_id":lid,"reason":plan[lid][1]})
    else:
        r = await propose_match({"line_id":lid,"invoice_ids":plan[lid][1],"rationale":plan[lid][2]})
    return lid, json.loads(r)

results=[]
for lid in plan:
    l,r = await decide(lid)
    results.append((l,r))

